                p[i] = find(p[i])
            return p[i]
        def union(i,j):
            pi, pj = find(i), find(j)
            p[pi] = pj
            newrank[pj] = max(newrank[pi], newrank[pj])
        for e in sorted(d):
            p = list(range(m+n))
            newrank = rank[:]
            for i, j in d[e]:
                union(i,m+j)
            for i, j in d[e]:
                rank[i] = rank[m+j] = matrix[i][j] = newrank[find(i)] + 1
        return matrix

